import React, { Component } from 'react';
import {
    CButton,
    CCard,
    CCardBody,
    CCardGroup,
    CCol,
    CContainer,
    CForm,
    CInput,
    CInputGroup,
    CInputGroupPrepend,
    CInputGroupText,
    CRow
} from '@coreui/react';
import CIcon from '@coreui/icons-react';
import { Logger, reloadPage } from '../../Utils/Utils';
import { requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';

const FILE_NAME = "CreatePerson.js";

class CreatePerson extends Component {

    constructor(props) {
        super(props);
        this.state = {
            name: '',
            emails: [''],
            phoneNumbers: [''],
            dob: '',
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
        };
    }

    componentDidMount() {
        document.title = "Create Person";
    }

    handleNameChange = (e) => {
        this.setState({ name: e.target.value });
    }

    handleDobChange = (e) => {
        this.setState({ dob: e.target.value });
    }

    // Email handlers
    handleEmailChange = (index, e) => {
        const emails = [...this.state.emails];
        emails[index] = e.target.value;
        this.setState({ emails });
    }

    addEmail = () => {
        this.setState(prev => ({ emails: [...prev.emails, ''] }));
    }

    removeEmail = (index) => {
        if (this.state.emails.length <= 1) return;
        const emails = this.state.emails.filter((_, i) => i !== index);
        this.setState({ emails });
    }

    // Phone handlers
    handlePhoneChange = (index, e) => {
        const phoneNumbers = [...this.state.phoneNumbers];
        phoneNumbers[index] = e.target.value;
        this.setState({ phoneNumbers });
    }

    addPhone = () => {
        this.setState(prev => ({ phoneNumbers: [...prev.phoneNumbers, ''] }));
    }

    removePhone = (index) => {
        if (this.state.phoneNumbers.length <= 1) return;
        const phoneNumbers = this.state.phoneNumbers.filter((_, i) => i !== index);
        this.setState({ phoneNumbers });
    }

    handleSubmit = (e) => {
        e.preventDefault();

        const { name, emails, phoneNumbers, dob } = this.state;

        const payload = {
            name,
            emails: emails.filter(email => email.trim() !== ''),
            phoneNumbers: phoneNumbers.filter(phone => phone.trim() !== ''),
            dob: dob || null,
        };

        Logger(FILE_NAME, "handleSubmit", "", "payload", payload);

        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/person';

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(payload), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ loadingModalVisible: false, failureModalVisible: true });
                setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "handleSubmit", "API_RESPONSE", "result", result);
            this.setState({ loadingModalState: 1 });
            setTimeout(() => this.resetForm(), 500);
        })
        .catch(error => {
            Logger(FILE_NAME, "handleSubmit", "API_ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    resetForm = () => {
        this.setState({
            name: '',
            emails: [''],
            phoneNumbers: [''],
            dob: '',
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
        });
    }

    render() {
        const { name, emails, phoneNumbers, dob } = this.state;

        return (
            <div>
                <a href="#/person" style={{ textDecoration: 'none' }}>
                    <CButton color="secondary" className="mb-3">← Back to Person Home</CButton>
                </a>
                <CContainer>
                    <CRow className="justify-content-center">
                        <CCol md="8">
                            <CCardGroup>
                                <CCard className="p-4">
                                    <CCardBody>
                                        <CForm onSubmit={this.handleSubmit}>
                                            <h1>Create Person</h1>
                                            <br />

                                            {/* Name */}
                                            <label><strong>Name *</strong></label>
                                            <CInputGroup className="mb-3">
                                                <CInputGroupPrepend>
                                                    <CInputGroupText>
                                                        <CIcon name="cilUser" />
                                                    </CInputGroupText>
                                                </CInputGroupPrepend>
                                                <CInput
                                                    placeholder="Full name"
                                                    type="text"
                                                    value={name}
                                                    onChange={this.handleNameChange}
                                                    required
                                                />
                                            </CInputGroup>

                                            {/* Emails */}
                                            <label><strong>Emails *</strong></label>
                                            {emails.map((email, index) => (
                                                <CInputGroup className="mb-2" key={'email-' + index}>
                                                    <CInputGroupPrepend>
                                                        <CInputGroupText>✉</CInputGroupText>
                                                    </CInputGroupPrepend>
                                                    <CInput
                                                        placeholder={'Email ' + (index + 1)}
                                                        type="email"
                                                        value={email}
                                                        onChange={(e) => this.handleEmailChange(index, e)}
                                                        required={index === 0}
                                                    />
                                                    {emails.length > 1 && (
                                                        <CButton
                                                            color="danger"
                                                            size="sm"
                                                            style={{ marginLeft: '8px' }}
                                                            onClick={() => this.removeEmail(index)}
                                                        >
                                                            ✕
                                                        </CButton>
                                                    )}
                                                </CInputGroup>
                                            ))}
                                            <CButton color="info" size="sm" className="mb-3" onClick={this.addEmail}>
                                                + Add Email
                                            </CButton>

                                            {/* Phone Numbers */}
                                            <br />
                                            <label><strong>Phone Numbers *</strong></label>
                                            {phoneNumbers.map((phone, index) => (
                                                <CInputGroup className="mb-2" key={'phone-' + index}>
                                                    <CInputGroupPrepend>
                                                        <CInputGroupText>📞</CInputGroupText>
                                                    </CInputGroupPrepend>
                                                    <CInput
                                                        placeholder={'Phone ' + (index + 1)}
                                                        type="tel"
                                                        value={phone}
                                                        onChange={(e) => this.handlePhoneChange(index, e)}
                                                        required={index === 0}
                                                    />
                                                    {phoneNumbers.length > 1 && (
                                                        <CButton
                                                            color="danger"
                                                            size="sm"
                                                            style={{ marginLeft: '8px' }}
                                                            onClick={() => this.removePhone(index)}
                                                        >
                                                            ✕
                                                        </CButton>
                                                    )}
                                                </CInputGroup>
                                            ))}
                                            <CButton color="info" size="sm" className="mb-3" onClick={this.addPhone}>
                                                + Add Phone
                                            </CButton>

                                            {/* DOB */}
                                            <br />
                                            <label><strong>Date of Birth</strong> (optional)</label>
                                            <CInputGroup className="mb-3">
                                                <CInputGroupPrepend>
                                                    <CInputGroupText>🎂</CInputGroupText>
                                                </CInputGroupPrepend>
                                                <CInput
                                                    placeholder="Date of Birth"
                                                    type="date"
                                                    value={dob}
                                                    onChange={this.handleDobChange}
                                                />
                                            </CInputGroup>

                                            <hr />
                                            <CRow>
                                                <CCol xs="6">
                                                    <CButton color="success" className="px-4" type="submit">CREATE</CButton>
                                                </CCol>
                                                <CCol xs="6" className="text-right">
                                                    <CButton color="danger" className="px-4" onClick={this.resetForm}>Reset</CButton>
                                                </CCol>
                                            </CRow>
                                        </CForm>
                                    </CCardBody>
                                </CCard>
                            </CCardGroup>
                        </CCol>
                    </CRow>
                </CContainer>
                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }
}

export default CreatePerson;
